/**
 * @summary Get top selling products
 */
export const getGetTopProductsUrl = (params?: GetTopProductsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/stats/top-products?${stringifiedParams}`
    : `/api/stats/top-products`;
};

export const getTopProducts = async (
  params?: GetTopProductsParams,
  options?: RequestInit,
): Promise<Product[]> => {
  return customFetch<Product[]>(getGetTopProductsUrl(params), {
    ...options,
    method: "GET",
  });
};

